pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: initialize contract, set MinSum to 100
        c.SetMinSum(100);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Two different users
        address alice = address(0x1111);
        address bob = address(0x2222);

        // Fund alice with 200 and deposit
        vm.deal(alice, 200);
        vm.prank(alice);
        c.Deposit{value: 100}();  // alice balance = 100

        // Fund bob with 200 and deposit
        vm.deal(bob, 200);
        vm.prank(bob);
        c.Deposit{value: 100}();  // bob balance = 100

        // Bob collects exactly MinSum (100)
        uint amount = 100;
        vm.prank(bob);
        c.Collect{value: 0}(amount);  // reference: bob balance becomes 0; buggy: bob balance becomes 200

        // Assert: reference bob balance == 0; buggy bob balance == 200
        // This assertion passes on reference (true) and fails on buggy (false)
        assertTrue(c.balances(bob) == 0, "Bob's balance should be 0 in reference contract");
    }
}

