pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Initialize MinSum
        c.SetMinSum(100);
        c.Initialized();
        // Fund caller with 1 ether and deposit 50
        address alice = address(0x123);
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.Deposit{value: 50}();
        // Now alice has balance 50, MinSum=100 => Collect(50) should revert in reference
        vm.prank(alice);
        // try-collect to detect revert vs success
        bool ok;
        try c.Collect(50) {
            ok = true;
        } catch {
            ok = false;
        }
        // In reference, ok == false (revert); in buggy, ok == true (succeeds)
        // Specifically check that alice's balance is still 50 (reference behavior) not 0
        // Use c.balances(alice) after the Collect call
        // Actually we need to observe difference: reference reverts so balance unchanged (50), bug succeeds so balance becomes 0.
        // But the assertion here must be that reference holds true: balance after Collect == 50.
        // For the test to pass on reference and fail on bug, assert that balance == 50.
        // We must re-query after the call (for reference, call reverted so state unchanged; for bug, state changed).
        vm.prank(alice);
        try c.Collect(50) {
            // succeeded (bug)
            ok = true;
        } catch {
            // reverted (reference)
            ok = false;
        }
        // Now alice's balance: if revert (ok false), remains 50; if succeeded, becomes 0.
        uint256 balAfter = c.balances(alice);
        // The property: reference has balAfter == 50, bug has balAfter == 0
        // So assert balAfter == 50, which holds for reference, fails for bug.
        assertTrue(balAfter == 50);
    }
}

